import{_ as e,c as r,o as p,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"24、【復】 震下坤上","description":"周易尚氏學 - 24、【復】 震下坤上","frontmatter":{"title":"24、【復】 震下坤上","description":"周易尚氏學 - 24、【復】 震下坤上"},"headers":[],"relativePath":"classics/shangshi/029.md","filePath":"classics/shangshi/029.md"}'),s={name:"classics/shangshi/029.md"};function t(h,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_24、【復】-震下坤上" tabindex="-1">24、【復】 震下坤上 <a class="header-anchor" href="#_24、【復】-震下坤上" aria-label="Permalink to “24、【復】 震下坤上”">​</a></h1><p>陽反故曰復。出人反覆。皆對姤言。復者姤之反。若舍股（左艮）不言。則復何所自乎。人者人巽。出者出震。坤為疾。象失傳。詳焦氏易詁陽通故無疾。陰以陽為朋。剝窮上反下故曰朋來。陽遇陰故無咎。陽自始而消。消至剝上。六日。反覆則七日。自復而息。息至決（無左）上。六日。反姤仍七日。循環不已。故曰反覆其道。七日來複。復陽長。故曰利有攸往。</p><p>彖曰。復亨。剛反。動而以順行。是以出入無疾。朋來無咎。反覆其道。七日來複。天行也。利有攸往。剛長也。復其見天地之心乎。</p><p>震動坤順。故日動而以順。天行。天道也。言陰陽剛柔往來消長。天道固如斯也。此天地之心也。坤為心。象失傳。詳魚氏易詁此以爻數括天地間之公例公理。其謂卦氣起中孚。至復為七日。不推於數不合。只六日七分且於理大謬。是皆執於自姤至復為七月。經言七日故疑也。豈知易辭皆舉一例。包括萬有。十日數至七必相反。辰數亦然即以日言。幽（內雙豕）詩云一之日。二之日。日皆謂月。侯果已言之矣。陰陽相遇為朋。自此象失傳。皆用卦變。俟陽息至二成兌。二陽為朋。虞氏之說訛誤至今。又五行志。京房易傳曰。復崩來無咎。讀朋為崩。是用覆象。謂剝艮覆在下為山崩。而易林遇此象。亦往往曰山崩。京所受也。其詳皆在焦氏易詁中。覆象久失傳。後惟惠棟用此說。實易言覆象者。不止此也。</p><p>象曰。雷在地中。復。先王以至曰閉關。商旅不行。後不省方。</p><p>曰至日則兼二至言也。姤雲。施命浩四方。即誥戒商旅將閉關也。易林晉之解。所謂二至之戒也。蓋古最重二至。漢書薛宣傳。日至休吏。所繇來久。後漢魯恭傳。易五月用事。先王施命令止四方行者。是夏至亦休息。與冬至同、坤為門戶。故曰關。震為商旅。坤閉故曰閉關。曰不行。坤為方。震為王。</p><p>初九。不遠復，無祗悔，元吉。</p><p>覆在內。故曰不遠復。嚴元照雲。只從氏非。此當從氏。氏是同用。故王肅作提（左衣）。坎低既平。京房亦作提王陶廬雲。唐石經即作祗。氏是古同部。故得同用。若氏（下、）則另為一部。不同部者不相假。古之例也。然則今作祗者誤也，襖鄭雲病也。段玉裁雲。鄭蓋借祗為氏（加　）。按祗之訓病。詩小雅何人斯。壹者之來。俾我祗也。毛傳祗病也。茲訓為病。正本毛傳。段謂借襖為氏（加　）非。病猶苗（中　）也。復出人無疾。故無苗（中　）悔。乾元通。故元吉。</p><h3 id="象曰。不遠之復。以修身也。坤為身。陽微故宜修養以待。" tabindex="-1">象曰。不遠之復。以修身也。坤為身。陽微故宜修養以待。 <a class="header-anchor" href="#象曰。不遠之復。以修身也。坤為身。陽微故宜修養以待。" aria-label="Permalink to “象曰。不遠之復。以修身也。坤為身。陽微故宜修養以待。”">​</a></h3><p>六二。休復。吉。</p><p>休者俟也。俟陽息至二故吉。</p><h3 id="象曰。休復之吉。以下仁也。" tabindex="-1">象曰。休復之吉。以下仁也。 <a class="header-anchor" href="#象曰。休復之吉。以下仁也。" aria-label="Permalink to “象曰。休復之吉。以下仁也。”">​</a></h3><p>仁者初也。陽主生故曰仁。以下仁者。言下陽即息至二。靜俟則吉也。</p><p>六三。頻復。厲。無咎。</p><p>虞翻曰。頻蹙也。三失位。故頻復。按頻古文顰字。故云頻蹙。三失位。承乘皆陰。又無應予。失類極</p><h3 id="象曰。頻復之厲。義無咎也。" tabindex="-1">象曰。頻復之厲。義無咎也。 <a class="header-anchor" href="#象曰。頻復之厲。義無咎也。" aria-label="Permalink to “象曰。頻復之厲。義無咎也。”">​</a></h3><p>六四。中行獨復。</p><p>文言乾九四雲。中不在人。中謂三四。居一卦之中也。又繫辭雲。其初難知。其上易知。若夫雜物撰德。非其中爻不備。中爻謂中四交。即下所謂二與四三與五也。四居卦中。獨與初應。故曰中行獨復。虞翻謂四不在二五。何得稱中行。豈知三四稱中爻。易固有明例也。</p><h3 id="象曰。中行獨復。以從道也。" tabindex="-1">象曰。中行獨復。以從道也。 <a class="header-anchor" href="#象曰。中行獨復。以從道也。" aria-label="Permalink to “象曰。中行獨復。以從道也。”">​</a></h3><p>道謂初。從道謂應初。</p><p>六五。敦復。無悔。</p><p>敦與屯通。詩大雅鋪敦淮憤（左水）。箋敦當作屯。揚雄甘泉賦。敦萬騎於中營兮。注敦與屯同。又按幽（雙豕）風雲。敦彼獨宿。即屯彼獨宿也。屯者止也。次也。而敦又與頓同。爾雅釋丘。丘一成為敦丘。疏即衛風之頓丘。頓亦止也。史記王翦傳三日三夜不頓舍。是也。是敦有止意待意。敦復者言五應在二。陽即升二。五稍待即有應也。故臨上六亦曰敦臨。以上六亦稍待。陽即息三。有應也。舊詁皆訓為敦厚。非。</p><h3 id="象曰。敦復無悔。中以自者也。" tabindex="-1">象曰。敦復無悔。中以自者也。 <a class="header-anchor" href="#象曰。敦復無悔。中以自者也。" aria-label="Permalink to “象曰。敦復無悔。中以自者也。”">​</a></h3><p>向秀曰。考察也。五中位。應在二。亦中位。陽息即至二。五有應。故無侮。中以自考者。釋敦之故。易之道貴將來。言頓止以待中二之陽息。自考省也。與臨上之志在內義同。</p><p>上六。迷復。兇。有災眚。用行師。終有大敗。以其國君兇。至於十年不克徵。</p><p>凡上六多不吉。上窮也。坤為迷為死喪。故有災眚。坤為眾故為師。坤為死喪。故行師終有大敗。坤為國。震為君。象失傳。詳焦氏易詁故曰國君。坤為十年。震為徵。不克徵。言不能興起也。比上六後夫兇。師上六小人勿用。皆以其不承陽也。他爻皆可承陽。獨上六不能不承陽則背叛君命。而殃及國君。故曰以其為君兇。君者國之本。國君受協。根本動搖。故其兇至於十年也。</p><h3 id="象曰。迷復之兇。反君道也。" tabindex="-1">象曰。迷復之兇。反君道也。 <a class="header-anchor" href="#象曰。迷復之兇。反君道也。" aria-label="Permalink to “象曰。迷復之兇。反君道也。”">​</a></h3><p>反君道。即謂上六不承陽。舊解皆以不順君命為反君道。然上六之何以獨反君道。其故無能明者。此與六五敦復。及臨之敦臨義晦同也。</p>',28)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
